module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

parameter IDLE = 2'b00;
parameter DETECTING_PULSE = 2'b01;
parameter END_OF_PULSE = 2'b10;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1)
                    state <= DETECTING_PULSE;
            end
            DETECTING_PULSE: begin
                if (data_in == 1'b0)
                    state <= END_OF_PULSE;
            end
            END_OF_PULSE: begin
                if (data_in == 1'b1) state <= DETECTING_PULSE; else state <= IDLE;
            end
        endcase
    end
end

always @(*) begin
    data_out = (state == DETECTING_PULSE) && (data_in == 1'b0);
end

endmodule
